--   ('84755a7b-fe7d-4be7-b306-40d38dd07aef'::uuid, $l2v${"title":"Compléter une addition à trou","description":"Relatifs entre $-7$ et $7$. À l'aide de la droite graduée.","variations":[{"blanks":[{"expectedAnswer":"{{b}}"}],"statement":"Complète en t'aidant de la droite graduée.\n\n$${{expression1}}$$\n\n![Question image 1](relatifs/droite-graduee-operations/droite-graduee--7-7-600.png)","variables":[{"name":"a","expression":"1..7"},{"name":"b","expression":"1..8"},{"name":"expression1","expression":"(-{{a}})+?= {{eval:(-a)+b}}"}],"correction":{"steps":["**Sur la droite graduée**, ajouter un nombre positif, c’est avancer vers la droite ; soustraire un nombre positif, c’est reculer vers la gauche.","Sur la droite graduée, pour aller de ${{if:(-a)<0|\\textcolor{{{color:primary.0}}}{-}{{eval:abs(-a)}}|{{eval:-a}}}}$ à ${{if:(-a+b)<0|\\textcolor{{{color:primary.0}}}{-}{{eval:abs(-a+b)}}|{{eval:-a+b}}}}$, {{if:(-a+b)>(-a)|on $\\textcolor{{{color:primary.1}}}{\\text{avance}}$ vers la droite|on $\\textcolor{{{color:primary.1}}}{\\text{recule}}$ vers la gauche}} : c’est {{if:(-a+b)>(-a)|ajouter un nombre $\\textcolor{{{color:primary.2}}}{\\text{positif}}$|ajouter un nombre $\\textcolor{{{color:primary.2}}}{\\text{négatif}}$}}.","Sa distance à zéro est l’écart entre ${{if:(-a)<0|\\textcolor{{{color:primary.0}}}{-}{{eval:abs(-a)}}|{{eval:-a}}}}$ et ${{if:(-a+b)<0|\\textcolor{{{color:primary.0}}}{-}{{eval:abs(-a+b)}}|{{eval:-a+b}}}}$ : {{if:(-a)*(-a+b)=0|l’un des deux est $0$, l’écart est la distance à zéro de l’autre.|{{if:(-a)*(-a+b)<0|ils sont de part et d’autre de zéro, on additionne leurs distances à zéro.|ils sont du même côté de zéro, on soustrait leurs distances à zéro.}}}}","$$\\begin{align} ? &= \\textcolor{{{color:primary.2}}}{{{if:(-a+b)>(-a)|+|-}}}\\left( {{if:(-a)*(-a+b)=0|{{eval:abs(-a)+abs(-a+b)}}|{{if:(-a)*(-a+b)<0|{{eval:abs(-a)}} + {{eval:abs(-a+b)}}|{{if:(-a)*(-a)>(-a+b)*(-a+b)|{{eval:abs(-a)}} - {{eval:abs(-a+b)}}|{{eval:abs(-a+b)}} - {{eval:abs(-a)}}}}}}}} \\right) \\\\ &= {{solution}} \\end{align}$$"]}},{"blanks":[{"expectedAnswer":"{{b}}"}],"statement":"Complète en t'aidant de la droite graduée.\n\n$${{expression2}}$$\n\n![Question image 1](relatifs/droite-graduee-operations/droite-graduee--7-7-600.png)","variables":[{"name":"a","expression":"1..6"},{"name":"b","expression":"1..{{eval:7-a}}"},{"name":"expression2","expression":"(-{{a}})-?={{eval:(-a)-b}}"}],"correction":{"steps":["**Sur la droite graduée**, ajouter un nombre positif, c’est avancer vers la droite ; soustraire un nombre positif, c’est reculer vers la gauche.","Sur la droite graduée, pour aller de ${{if:(-a)<0|\\textcolor{{{color:primary.0}}}{-}{{eval:abs(-a)}}|{{eval:-a}}}}$ à ${{if:(-a-b)<0|\\textcolor{{{color:primary.0}}}{-}{{eval:abs(-a-b)}}|{{eval:-a-b}}}}$, {{if:(-a-b)>(-a)|on $\\textcolor{{{color:primary.1}}}{\\text{avance}}$ vers la droite|on $\\textcolor{{{color:primary.1}}}{\\text{recule}}$ vers la gauche}} : c’est {{if:(-a-b)>(-a)|soustraire un nombre $\\textcolor{{{color:primary.2}}}{\\text{négatif}}$|soustraire un nombre $\\textcolor{{{color:primary.2}}}{\\text{positif}}$}}.","Sa distance à zéro est l’écart entre ${{if:(-a)<0|\\textcolor{{{color:primary.0}}}{-}{{eval:abs(-a)}}|{{eval:-a}}}}$ et ${{if:(-a-b)<0|\\textcolor{{{color:primary.0}}}{-}{{eval:abs(-a-b)}}|{{eval:-a-b}}}}$ : {{if:(-a)*(-a-b)=0|l’un des deux est $0$, l’écart est la distance à zéro de l’autre.|{{if:(-a)*(-a-b)<0|ils sont de part et d’autre de zéro, on additionne leurs distances à zéro.|ils sont du même côté de zéro, on soustrait leurs distances à zéro.}}}}","$$\\begin{align} ? &= \\textcolor{{{color:primary.2}}}{{{if:(-a-b)>(-a)|-|+}}}\\left( {{if:(-a)*(-a-b)=0|{{eval:abs(-a)+abs(-a-b)}}|{{if:(-a)*(-a-b)<0|{{eval:abs(-a)}} + {{eval:abs(-a-b)}}|{{if:(-a)*(-a)>(-a-b)*(-a-b)|{{eval:abs(-a)}} - {{eval:abs(-a-b)}}|{{eval:abs(-a-b)}} - {{eval:abs(-a)}}}}}}}} \\right) \\\\ &= {{solution}} \\end{align}$$"]}},{"blanks":[{"expectedAnswer":"{{b}}"}],"statement":"Complète en t'aidant de la droite graduée.\n\n$${{expression3}}$$\n\n![Question image 1](relatifs/droite-graduee-operations/droite-graduee--7-7-600.png)","variables":[{"name":"a","expression":"1..7"},{"name":"b","expression":"{{eval:a+1}}..8"},{"name":"expression3","expression":"{{a}}-?={{eval:a-b}}"}],"correction":{"steps":["**Sur la droite graduée**, ajouter un nombre positif, c’est avancer vers la droite ; soustraire un nombre positif, c’est reculer vers la gauche.","Sur la droite graduée, pour aller de ${{if:(a)<0|\\textcolor{{{color:primary.0}}}{-}{{eval:abs(a)}}|{{eval:a}}}}$ à ${{if:(a-b)<0|\\textcolor{{{color:primary.0}}}{-}{{eval:abs(a-b)}}|{{eval:a-b}}}}$, {{if:(a-b)>(a)|on $\\textcolor{{{color:primary.1}}}{\\text{avance}}$ vers la droite|on $\\textcolor{{{color:primary.1}}}{\\text{recule}}$ vers la gauche}} : c’est {{if:(a-b)>(a)|soustraire un nombre $\\textcolor{{{color:primary.2}}}{\\text{négatif}}$|soustraire un nombre $\\textcolor{{{color:primary.2}}}{\\text{positif}}$}}.","Sa distance à zéro est l’écart entre ${{if:(a)<0|\\textcolor{{{color:primary.0}}}{-}{{eval:abs(a)}}|{{eval:a}}}}$ et ${{if:(a-b)<0|\\textcolor{{{color:primary.0}}}{-}{{eval:abs(a-b)}}|{{eval:a-b}}}}$ : {{if:(a)*(a-b)=0|l’un des deux est $0$, l’écart est la distance à zéro de l’autre.|{{if:(a)*(a-b)<0|ils sont de part et d’autre de zéro, on additionne leurs distances à zéro.|ils sont du même côté de zéro, on soustrait leurs distances à zéro.}}}}","$$\\begin{align} ? &= \\textcolor{{{color:primary.2}}}{{{if:(a-b)>(a)|-|+}}}\\left( {{if:(a)*(a-b)=0|{{eval:abs(a)+abs(a-b)}}|{{if:(a)*(a-b)<0|{{eval:abs(a)}} + {{eval:abs(a-b)}}|{{if:(a)*(a)>(a-b)*(a-b)|{{eval:abs(a)}} - {{eval:abs(a-b)}}|{{eval:abs(a-b)}} - {{eval:abs(a)}}}}}}}} \\right) \\\\ &= {{solution}} \\end{align}$$"]}}],"shared":null,"test_specs":[{"answers":["1"],"expected":{"status":"correct"},"variables":{"a":"3","b":"1"},"description":"(-3)+? = -2 → 1","variationIndex":0},{"answers":["-1"],"expected":{"status":"incorrect"},"variables":{"a":"3","b":"1"},"description":"signe inversé","variationIndex":0},{"answers":["+1"],"expected":{"status":"unoptimal_form","constraintViolations":["signs"]},"variables":{"a":"3","b":"1"},"description":"signe + superflu","variationIndex":0},{"answers":["(1)"],"expected":{"status":"correct"},"variables":{"a":"3","b":"1"},"description":"parenthèses tolérées (option TinyMath)","variationIndex":0},{"answers":["8"],"expected":{"status":"correct"},"variables":{"a":"1","b":"8"},"description":"borne haute : (-1)+? = 7","variationIndex":0},{"answers":["1"],"expected":{"status":"correct"},"variables":{"a":"3","b":"1"},"description":"(-3)-? = -4 → 1","variationIndex":1},{"answers":["-1"],"expected":{"status":"incorrect"},"variables":{"a":"3","b":"1"},"description":"signe inversé (soustraction)","variationIndex":1},{"answers":["4"],"expected":{"status":"correct"},"variables":{"a":"1","b":"4"},"description":"1-? = -3 → 4","variationIndex":2},{"answers":["-3"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"4"},"description":"résultat recopié","variationIndex":2}]}$l2v$::jsonb),
